const D = { energy:.6, scale:1, density:.5, speed:1, hue:32, arms:.6, breathe:.55, x:.5, y:.5, style:'plate', seed:0, alpha:100 };
const P = Object.assign({}, D, (window.state.P && window.state.P.__SLOT__) || {});
const S = window.state.__SLOT__ || (window.state.__SLOT__ = {});
const K = window.state.clk || { t:0, cps:.5, beat:0, bar:0, cyc:0, phase:0, pulse:0, swell:0, section:0, intensity:.6, fps:60 };
const A = window.state.audio || { bass:0, lowmid:0, mid:0, treble:0, rms:0, fft:[] };

const cl = (v,a,b) => v<a?a:(v>b?b:v);
const sst = (e0,e1,x) => { const t = cl((x-e0)/(e1-e0), 0, 1); return t*t*(3-2*t); };
const u = Math.min(width, height);
const sd = P.seed|0;
const fr = i => { const s = Math.sin(i*127.1 + sd*311.7)*43758.5453; return s - Math.floor(s); };
const sty = P.style, H = ((P.hue%360)+360)%360, en = cl(P.energy,0,1);

if (S.pt == null || K.t < S.pt) S.pt = K.t;
S.pt = K.t;
const sp = .25 + .75*P.speed;
const lift = .55 + .45*K.intensity;
const bass = (S.b = (S.b||0)*.84 + (A.bass||0)*.16);

// ---- Robinson's hierarchy of nested squares ------------------------------
// A level-k centre sits at every point ( 2^k(2i+1), 2^k(2j+1) ) -- i.e. exactly
// where the 2-adic valuations of x and y are both k. Levels are disjoint, and
// scaling by 2 maps level k onto level k+1 EXACTLY: the hierarchy is its own
// inflation. So we can zoom forever and simply slide the drawn level window.
// z is kept as frac(z) and levels are indexed off the SCREEN spacing only, so
// nothing ever overflows and the wrap at each doubling is seamless.
const z = K.t*.052*sp + (.95*Math.sin(K.t*.041) + .52*Math.sin(K.t*.0973+1.3))*cl(P.breathe,0,1);
const M = Math.pow(2, z - Math.floor(z));                  // in [1,2)
const base = u*.030;
const rot = .17*Math.sin(K.t*.0431*sp) + .09*Math.sin(K.t*.1097*sp+2.2);   // bounded -> cheap culling

const ax = cl(P.x,.2,.8)*width, ay = cl(P.y,.2,.8)*height;
const ca = Math.abs(Math.cos(rot)), sa = Math.abs(Math.sin(rot));
const dxm = Math.max(ax, width-ax), dym = Math.max(ay, height-ay);
const hx = dxm*ca + dym*sa, hy = dxm*sa + dym*ca;

// motif proportions (NOT overall size: a self-similar zoom would swallow that
// whole and the params poke would be a no-op -- so scale drives the geometry)
const sqF  = cl(.86*P.scale, .25, 1.35);
const armF = cl(.95*P.scale*(.45+.9*cl(P.arms,0,1)), .25, 1.7);
const minPx = cl(240 - 150*cl(P.density,0,1), 105, 260);
const maxPx = Math.max(u*2.9, minPx*4.2);
const kmin = Math.ceil (Math.log(minPx/(base*M))/Math.LN2 - 1);
const kmax = Math.floor(Math.log(maxPx/(base*M))/Math.LN2 - 1);

// ---- style tables ---------------------------------------------------------
const glow = (sty==='xray');
function paper(){
  if (sty==='blueprint') return [212, 64, 40];
  if (sty==='lead')      return [230, 40, 16];
  if (glow)              return [(H+190)%360, 58, 5];
  if (sty==='concrete')  return [(H+180)%360, 5, 62];
  return [(H+3)%360, 12, 89];
}
function ink(){
  if (sty==='blueprint') return [192, 22, 98];
  if (sty==='lead')      return [(H)%360, 8, 92];
  if (glow)              return [(H+160)%360, 36, 99];
  if (sty==='concrete')  return [(H+180)%360, 6, 22];
  return [(H-16+360)%360, 56, 22];
}
// tone of a level's square wash, keyed on SCREEN spacing (never on k) so the
// doubling wrap is invisible
function wash(q){
  if (sty==='blueprint') return [206, 42, 92];
  if (sty==='lead')      return [(H + 40 + q*220)%360, 62, 86];
  if (glow)              return [(H + 140 + q*90)%360, 44, 90];
  if (sty==='concrete')  return [(H+180)%360, 4, 82];
  return [(H + 6 + q*14)%360, 26, 88];
}

const pc = paper(); noStroke(); background(pc[0], pc[1], pc[2]);
const ic = ink();

push(); translate(ax, ay); rotate(rot);
rectMode(CENTER); strokeJoin(MITER);
blendMode(glow ? ADD : MULTIPLY);

for (let k=kmin; k<=kmax; k++){
  const spc = Math.pow(2, k+1)*base*M;                      // screen spacing
  if (!isFinite(spc) || spc <= 0) continue;
  const aL = sst(minPx, minPx*1.55, spc) * (1 - sst(maxPx*.60, maxPx, spc));
  if (aL < .012) continue;
  const half = spc*.5, sq = half*sqF, arm = half*armF;
  const q = cl((Math.log(spc/minPx)/Math.LN2)/4.2, 0, 1);   // depth 0..1 within the window
  const rich = spc > u*.24;
  const ni = Math.ceil(hx/half*.5)+1, nj = Math.ceil(hy/half*.5)+1;
  const wc = wash(q);
  const aw = aL*(6 + 15*en)*(glow ? 1.5 : 1);
  const ai = aL*(46 + 44*en);
  const lw = (u/900)*(.5 + 1.9*en)*(.55 + .9*q);
  for (let i=-ni;i<=ni;i++){
    const cx = (2*i+1)*half;
    if (Math.abs(cx) > hx + sq) continue;
    for (let j=-nj;j<=nj;j++){
      const cy = (2*j+1)*half;
      if (Math.abs(cy) > hy + sq) continue;
      const jit = fr(i*13.7 + j*29.3 + k*7.1);
      // tonal wash: nested translucent squares stack into real tonal depth
      noStroke();
      fill(wc[0], wc[1], glow ? wc[2]*(.5+.5*jit) : wc[2], aw*(.7+.6*jit));
      rect(cx, cy, sq*2, sq*2);
      // the square frame
      noFill();
      stroke(ic[0], ic[1], glow ? cl(ic[2]*(.5+.6*q+.4*bass),0,100) : ic[2], ai);
      strokeWeight(lw);
      rect(cx, cy, sq*2, sq*2);
      if (rich) {
        // the cross whose arms bind this square to its four children
        strokeWeight(lw*1.5);
        stroke(ic[0], ic[1], ic[2], ai*.92);
        line(cx-arm, cy, cx+arm, cy);
        line(cx, cy-arm, cx, cy+arm);
        // engraved hatching inside the frame -> texture, not flat fill
        const nh = 3 + ((i+j+k)&1);
        strokeWeight(lw*.42);
        stroke(ic[0], cl(ic[1]*.8,0,100), ic[2], ai*(.20+.22*en));
        for (let h=1;h<=nh;h++){
          const f = -sq + (2*sq)*h/(nh+1);
          line(cx+f, cy-sq, cx+f, cy+sq);
        }
        // corner pips mark the four child centres
        noStroke();
        fill(ic[0], ic[1], ic[2], ai*.8);
        const cq = half*.5;
        for (let s=0;s<4;s++)
          ellipse(cx + (s&1?cq:-cq), cy + (s&2?cq:-cq), lw*2.4, lw*2.4);
      }
    }
  }
}
blendMode(BLEND); rectMode(CORNER); pop();

// ---- moving chiaroscuro, built coarse and multiplied down once ------------
const lw2 = 184, lh2 = cl(Math.round(184*height/Math.max(1,width)), 60, 340);
if (!S.lg || S.lgk !== lw2+'x'+lh2) { S.lg = createGraphics(lw2, lh2); S.lg.colorMode(HSB,360,100,100,100); S.lgk = lw2+'x'+lh2; }
const L = S.lg;
L.push(); L.noStroke(); L.blendMode(BLEND);
L.background(0, 0, 100 - (22 + 30*en));
L.blendMode(ADD);
const px2 = (.5 + .28*Math.sin(K.t*.071+.4) + .12*Math.sin(K.t*.183+2.1))*lw2;
const py2 = (.5 + .25*Math.cos(K.t*.059+1.7) + .11*Math.sin(K.t*.149+.8))*lh2;
for (let i=0;i<9;i++){
  const t2 = i/8, rr = Math.max(lw2,lh2)*(1.28 - t2*1.0);
  L.fill(0, 0, 100, (7 + 7*en + 5*bass)*(.28 + .72*t2*t2));
  L.ellipse(px2, py2, rr*2, rr*2);
}
L.blendMode(BLEND); L.pop();
blendMode(MULTIPLY); noStroke(); image(L, 0, 0, width, height); blendMode(BLEND);

// ---- cached plate grain ---------------------------------------------------
const tk = sty+'|'+sd;
if (!S.tex || S.texk !== tk) {
  const tw=430, th=290, t=createGraphics(tw,th);
  t.colorMode(HSB,360,100,100,100); t.background(0,0,100); t.noStroke();
  for (let i=0;i<2300;i++){
    const rr = .4 + fr(i*5.13)*1.8;
    t.fill(30, 7, 100 - fr(i*7.91)*44, 54);
    t.ellipse(fr(i*1.97)*tw, fr(i*3.11+7.3)*th, rr, rr);
  }
  S.tex = t; S.texk = tk;
}
blendMode(MULTIPLY); noStroke(); image(S.tex, 0, 0, width, height); blendMode(BLEND);

if (P.alpha < 100) { noStroke(); fill(0,0,0, 100 - cl(P.alpha,0,100)); rect(0,0,width,height); }
blendMode(BLEND); drawingContext.shadowBlur = 0;
